declare patch jsonb; prior shared.ai_prompt_versions; template shared.ai_prompt_versions; prompt_uuid uuid; version_uuid uuid; next_version integer; definition jsonb; activation jsonb:='{}'; policy jsonb:=$parameter_policy${"name":"change_construction_parameters","description":"Change saved construction input nodes; server recomputes dependencies and retains exact version history.","how_to":"Read the existing construction and parameter IDs. Supply only same-role/unit input changes, or an updated revision of the same source measurement. Reuse key only for exact retry. The server preserves formulas, geometry topology, materials and joints. Check the receipt revision and pass it as construction_revision to design_project_cad; no drawing is saved by this command.","schema_version":1,"always_load":false,"preload_phases":[],"active":true}$parameter_policy$::jsonb;
